CREATE OR ALTER function [dbo].[CheckIfAssetExistsWithParent]
(	
	@AssetTypeID int,
	@AssetID bigint, 
	@Fields nvarchar(max), 
	@ParentID int = -1
)
returns bit
as
begin
	declare @ObjectType varchar(50);
	declare @ObjectTypeID int;
	declare @ObjectID int;

	--wrapper around CheckIfObjectExistsWithParent until that is rewritten purely for assets / asset types this way we have one set of logic for both and not 2...
	select 
		@ObjectType = ATT.[Object], @ObjectTypeID = ATT.[ObjectID], @ObjectID = A.ObjectID 
	from 
		AssetType ATT 
		inner join Asset A on (A.AssetTypeID = ATT.ID) 
	where 
		ATT.ID = @AssetTypeID and A.ID = @AssetID;

	return [dbo].[CheckIfObjectExistsWithParent](@ObjectType,@ObjectTypeID,@ObjectID,@Fields,@ParentID);
end

begin DECLARE @max int; SELECT @max = max(ObjectID) +1 from Asset;
exec('CREATE SEQUENCE Asset_ObjectID_Seq START WITH ' + @max + ' INCREMENT BY 1;')
end
